import XCTest
@testable import MirNavigation
final class ClassicWorldReplayTests:XCTestCase {
 func testCapturedNPCAndAnimalMessages() throws {
  let hexes=["3d74524b6f626863446656736664686b6464686b6464686b6464686b6464686b6464686b643f",
"",
"605c4a4d786668697266693f6666686a676448436464686b64644b403e3f5e6261556a",
"45784c587166686145666a436664686b676449436464686b64644b56413f696261556a",
"61486c6e6766686546665a7766656a6a6264696b6464686b64644b5a5078595b545f5b41503f696261556a"]
  var ids:Set<UInt16>=[]
  for hex in hexes {
   let c=Array(hex)
   let bytes=stride(from:0,to:c.count,by:2).map { UInt8(String(c[$0...($0+1)]),radix:16)! }
   ids.insert(try MirWire.packet(bytes).id)
  }
  XCTAssertTrue(ids.contains(643));XCTAssertTrue(ids.contains(50));XCTAssertTrue(ids.contains(10))
 }
}
